import java.util.*;

class Solution {
    public int josephus(int n, int k) {
        ArrayList<Integer> people = new ArrayList<>();

        for (int person = 1; person <= n; person++) {
            people.add(person);
        }

        int removeIndex = 0;

        while (people.size() > 1) {
            removeIndex = (removeIndex + k - 1) % people.size();
            people.remove(removeIndex);
        }

        return people.get(0);
    }
}
